// кнопка «Показать график» есть на одной странице из двадцати,
// поэтому библиотеку графиков не кладут в общий бандл

const button = document.querySelector('#show-chart');

button.addEventListener('click', async function () {
  const chart = await import('./chart.js');   // сборщик сделает из этого отдельный чанк
  chart.render(document.querySelector('#chart'));
});

// при сборке получится:
//   assets/index-9d41f0a2.js    14.8 kB  — грузится сразу
//   assets/chart-4b7c1e2f.js   182.3 kB  — грузится только по клику

# nginx: HTML не кэшируем, файлы с хэшем — на год
location = /index.html {
  add_header Cache-Control "no-cache";
}

location /assets/ {
  add_header Cache-Control "public, max-age=31536000, immutable";
}

Первая загрузка:   index.html (0.5 КБ) + assets/index-3f2a1c.js (14.8 КБ)
Повторная:         index.html перепроверяется (304), JS берётся из кэша диска
Выпустили правку:  имя стало index-8c05de.js -> браузер скачивает новый файл

Без хэша в имени вторая схема невозможна: max-age=31536000 на обычном
app.js означал бы, что посетитель год видит старую версию.
